// Approved Step 3 design: 5 keywords x 2 countries, but only TWO
// SerpApi requests per run (one multi-query request per country).
const keywords = ["n8n", "n8n workflow", "workflow automation", "n8n template", "no code automation"];
const countries = ["US", "IN"];

// ~60-day window as a custom SerpApi google_trends date range.
const end = new Date();
const start = new Date(Date.now() - 60 * 24 * 3600 * 1000);
const fmt = (d) => d.toISOString().slice(0, 10);
const date = fmt(start) + " " + fmt(end);

const items = [];
for (const country of countries) {
  items.push({ json: { country, q: keywords.join(","), keywords, date } });
}
return items;

// Each input item = one SerpApi multi-query TIMESERIES response.
// Pair it with its Config item by index to recover country + keywords.
const configItems = $('Config').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const resp = inputs[i].json || {};
  const ctx = (configItems[i] && configItems[i].json) || {};
  const country = ctx.country || "";
  const keywords = ctx.keywords || [];

  const timeline =
    (resp.interest_over_time && resp.interest_over_time.timeline_data) || [];

  // Transpose: keyword k -> its own time series across all timeline points.
  for (let k = 0; k < keywords.length; k++) {
    const keyword = keywords[k];
    const points = [];
    for (const p of timeline) {
      const v = p.values && p.values[k] ? p.values[k].extracted_value : null;
      if (typeof v === "number") points.push(v);
    }

    let trendInterest = 0;
    let trendChangePct = 0;
    if (points.length > 0) {
      const sum = points.reduce((a, b) => a + b, 0);
      trendInterest = Math.round((sum / points.length) * 100) / 100;

      // Momentum: last quarter avg vs first quarter avg of the window.
      const q = Math.max(1, Math.floor(points.length / 4));
      const firstAvg = points.slice(0, q).reduce((a, b) => a + b, 0) / q;
      const lastAvg = points.slice(-q).reduce((a, b) => a + b, 0) / q;
      if (firstAvg > 0) {
        trendChangePct =
          Math.round(((lastAvg - firstAvg) / firstAvg) * 10000) / 100;
      }
    }

    // Trends score: relative interest + positive-momentum bonus (own 0-100 scale).
    const popularityScore =
      Math.round((trendInterest * 5 + Math.max(trendChangePct, 0) * 2) * 100) / 100;

    const slug = String(keyword)
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
    const sourceId = "trends_" + country + "_" + slug;
    const sourceUrl =
      "https://trends.google.com/trends/explore?q=" +
      encodeURIComponent(keyword) +
      "&geo=" +
      country;

    out.push({
      json: {
        workflow: keyword,
        platform: "trends",
        country,
        keyword,
        views: 0,
        likes: 0,
        comments: 0,
        replies: 0,
        contributors: 0,
        trend_interest: trendInterest,
        trend_change_pct: trendChangePct,
        like_to_view_ratio: 0,
        comment_to_view_ratio: 0,
        popularity_score: popularityScore,
        source_id: sourceId,
        source_url: sourceUrl,
        channel_title: "Google Trends",
        published_at: "",
        collected_at: new Date().toISOString(),
      },
    });
  }
}

return out;
